 "src/Foundation/Bytes.lex.tex": "\\begin{lexlean}{Foundation.Bytes}\n\\useglossary{lexlean.std.bool@1.2.0}\n\\useglossary{lexlean.std.nat@1.2.0}\n\\useglossary{prism.arch@1.0.0}\n\\title{Bounded byte buffer}\n\\begin{semanticmodule}\ninductive{\n  name: ByteOrder,\n  type_parameters: [],\n  parameters: [],\n  constructors: [{name: LittleEndian, fields: []}, {name: BigEndian, fields: []}]\n}\n\ninductive{\n  name: BufferError,\n  type_parameters: [],\n  parameters: [],\n  constructors: [\n    {name: OutOfBounds, fields: []},\n    {name: LengthOverflow, fields: []},\n    {name: NonCanonical, fields: []}\n  ]\n}\n\nstructure{\n  name: BoundedBuffer,\n  type_parameters: [],\n  parameters: [],\n  fields: [{name: bytes, type: Bytes}, {name: maximum, type: UInt64}]\n}\n\ndefinition{\n  name: appendBytes,\n  parameters: [left : Bytes, right : Bytes],\n  result: Bytes,\n  body: (prim append left right : Bytes)\n}\n\ndefinition{\n  name: byteLength,\n  parameters: [value : Bytes],\n  result: Nat,\n  body: (prim length value : Nat)\n}\n\ndefinition{\n  name: byteAt,\n  parameters: [value : Bytes, offset : Nat],\n  result: (Option UInt8),\n  body: (prim index value offset : (Option UInt8))\n}\n\ndefinition{\n  name: sliceBytes,\n  parameters: [value : Bytes, start : Nat, count : Nat],\n  result: (Option Bytes),\n  body: (prim slice value start count : (Option Bytes))\n}\n\ndefinition{\n  name: compareBytes,\n  parameters: [left : Bytes, right : Bytes],\n  result: Ordering,\n  body: (prim compare_bytes left right : Ordering),\n  axioms: [propext]\n}\n\\end{semanticmodule}\n\\end{lexlean}\n",
